style.css:
/* Sugarcloud Sky — Roblox */

:root {
  /* swap these pastel colors if you want */
  --my-sky: #b9e6ff;
  --my-blue: #8bd3ff;
  --my-cloud: #ffffff;
  --my-pink: #ffd9ed;
  --my-lavender: #e8ddff;
  --my-text: #527b9e;
}

/* pastel sky background */
html,
body {
  background: linear-gradient(
    160deg,
    #d9f3ff 0%,
    #b9e6ff 45%,
    #e9e2ff 100%
  ) !important;
  color: var(--my-text) !important;
}

/* cute rounded panels */
section,
article,
main,
[role="main"] {
  border-radius: 20px !important;
}

/* kawaii buttons */
button,
[role="button"] {
  border-radius: 16px !important;
  border: 2px solid #ffffff !important;
  background: #a9ddff !important;
  color: #416f98 !important;
  box-shadow: 0 4px 0 #83c5ed !important;
}

/* cute pastel links */
a {
  color: #559acb !important;
  text-decoration-color: #b9e6ff !important;
}

/* soft image corners */
img {
  border-radius: 16px !important;
}

/* pastel text selection */
::selection {
  background: #ffcce8 !important;
  color: #527b9e !important;
}

/* adorable scrollbar */
::-webkit-scrollbar {
  width: 10px !important;
}

::-webkit-scrollbar-track {
  background: #e7f5ff !important;
}

::-webkit-scrollbar-thumb {
  background: #a9ddff !important;
  border-radius: 20px !important;
  border: 2px solid #e7f5ff !important;
}
